/**
 * The first workspace's slug: the display name slugified, or `workspace` when
 * that is shorter than the minimum slug length. Reserved and taken slugs are
 * suffixed by `uniqueSlug`, so a sign-up never fails on its name.
 */
async function firstWorkspaceSlug(displayName: string): Promise<string> {
  const derived = slugify(displayName);
  const base =
    derived.length >= SLUG_MIN_LENGTH ? derived : FALLBACK_WORKSPACE_SLUG;
  const taken = await orgRepo.listTakenOrgSlugs(base);
  return uniqueSlug(base, taken);
}

/**
 * `<name>'s workspace`, with the name cut (by whole characters) until the
 * whole string fits the workspace name limit.
 */
function workspaceNameFor(displayName: string): string {
  const room = WORKSPACE_NAME_MAX - WORKSPACE_SUFFIX.length;
  let name = "";
  for (const char of displayName) {
    if (name.length + char.length > room) break;
    name += char;
  }
  return `${name}${WORKSPACE_SUFFIX}`;
}

